package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen1Test {

    private FormElement formElement;
    private Element inputElement;
    private Element selectElement;
    private Element optionElement;
    private Element optionElementNotSelected;
    private Element radioElement;
    private Element checkboxElement;

    @Before
    public void setUp() {
        // Set up a form element with various input elements
        formElement = new FormElement(null, null, new Attributes());

        // Create input elements
        inputElement = new Element("input", new Attributes().put("name", "inputName").put("type", "text"));
        selectElement = new Element("select", new Attributes().put("name", "selectName"));
        optionElement = new Element("option", new Attributes().put("value", "optionValue").put("selected", "selected"));
        optionElementNotSelected = new Element("option", new Attributes().put("value", "optionValueNotSelected"));
        radioElement = new Element("input", new Attributes().put("name", "radioName").put("type", "radio").put("checked", "checked"));
        checkboxElement = new Element("input", new Attributes().put("name", "checkboxName").put("type", "checkbox").put("checked", "checked"));

        // Add elements to the form
        selectElement.appendChild(optionElement);
        selectElement.appendChild(optionElementNotSelected);
        formElement.addElement(inputElement);
        formElement.addElement(selectElement);
        formElement.addElement(radioElement);
        formElement.addElement(checkboxElement);
    }

    @Test
    public void testFormData_InputText() {
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("inputName", result.get(0).key());
        assertEquals("", result.get(0).value()); // Assuming input has no value set
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(2, result.size());
        assertTrue(result.stream().anyMatch(kv -> "selectName".equals(kv.key()) && "optionValue".equals(kv.value())));
    }

    @Test
    public void testFormData_SelectWithoutSelectedOption() {
        // Remove selected attribute from option
        optionElement.attributes().remove("selected");
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("selectName", result.get(0).key());
        assertEquals("optionValueNotSelected", result.get(0).value());
    }

    @Test
    public void testFormData_RadioChecked() {
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(2, result.size());
        assertTrue(result.stream().anyMatch(kv -> "radioName".equals(kv.key()) && "".equals(kv.value())));
    }

    @Test
    public void testFormData_CheckboxChecked() {
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(2, result.size());
        assertTrue(result.stream().anyMatch(kv -> "checkboxName".equals(kv.key()) && "".equals(kv.value())));
    }

    @Test
    public void testFormData_RadioUnchecked() {
        radioElement.attributes().remove("checked");
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertFalse(result.stream().anyMatch(kv -> "radioName".equals(kv.key())));
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        checkboxElement.attributes().remove("checked");
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertFalse(result.stream().anyMatch(kv -> "checkboxName".equals(kv.key())));
    }

    @Test
    public void testFormData_EmptyName() {
        Element elementWithEmptyName = new Element("input", new Attributes().put("name", "").put("type", "text"));
        formElement.addElement(elementWithEmptyName);
        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertFalse(result.stream().anyMatch(kv -> "".equals(kv.key())));
    }

    @Test
    public void testFormData_NoSubmitableElements() {
        // Clear form elements
        formElement = new FormElement(null, null, new Attributes());
        List<Connection.KeyVal> result = formElement.formData();
        assertTrue(result.isEmpty());
    }
}
